from gc_windows import gc_windows


def test_basic_sliding_window():
    # 'ATGC' -> 2 GC of 4 = 0.5 ; 'GCGC' -> 4 GC of 4 = 1.0
    assert gc_windows('ATGCGC', 4, 2) == [0.5, 1.0]


def test_window_longer_than_sequence():
    assert gc_windows('ATG', 10, 2) == []


def test_step_larger_than_window():
    # windows at i=0 ('ATGC') and i=6 ('GC..') -> only full window at 0 fits
    assert gc_windows('ATGCGCAA', 4, 6) == [0.5]

def gc_windows(seq, w, s):
    out = []
    for i in range(0, len(seq), s):
        win = seq[i:i+w]
        out.append(sum(1 for c in win if c in 'GC') / w)
    return out

